// ================= nginx.conf (edge) =================
# Shared cache zone for the video-delivery edge
proxy_cache_path /var/cache/nginx/video levels=1:2 keys_zone=video_cache:200m
                  max_size=50g inactive=24h use_temp_path=off;

upstream origin_upstream {
    server origin.internal:8080;
}

server {
    listen 443 ssl;
    server_name edge.starci.video;

    # Manifests, segments, and poster/thumbnail assets all flow through here
    location ~* \.(m3u8|ts|mp4|jpg|jpeg|png|webp)$ {
        proxy_cache video_cache;

        # Cache key: includes the full request URI (path + query string).
        # /playlist.m3u8?utm_source=fb&utm_campaign=launch
        # /playlist.m3u8?utm_source=tw&utm_medium=social
        # /playlist.m3u8   (no params at all)
        # all serve byte-identical content but hash to three DIFFERENT keys.
        proxy_cache_key "$scheme$request_method$host$request_uri";

        proxy_cache_valid 200 302 10m;
        proxy_cache_valid 404 1m;

        # Observability lever: HIT / MISS / EXPIRED / BYPASS per response
        add_header X-Cache-Status $upstream_cache_status;

        proxy_pass http://origin_upstream;
        proxy_set_header Host $host;
        proxy_set_header Accept-Encoding $http_accept_encoding;
    }
}

// ================= origin service: app.ts (Express-style) =================
import express from "express";
import session from "express-session";

const app = express();

// Recently added: a session middleware, mounted globally with no path
// scoping. It runs in front of EVERY route, including the public,
// non-personalized manifest/segment/poster routes served through the
// shared edge cache defined above.
app.use(
  session({
    secret: process.env.SESSION_SECRET as string,
    resave: false,
    saveUninitialized: true,
  })
);

app.use((req, res, next) => {
  // Stamped on every response, regardless of whether the route actually
  // personalizes anything. The edge cache keys on Vary, so this means one
  // cache entry per distinct session cookie for these public assets.
  res.setHeader("Vary", "Cookie");

  // Legitimate on its own, but varies on the raw client header value
  // instead of a canonical, normalized encoding set (e.g. gzip/br only),
  // fragmenting the cache further.
  res.append("Vary", "Accept-Encoding");

  next();
});

app.get("/playlist.m3u8", servePlaylistManifest);
app.get("/segments/:segmentId.ts", serveVideoSegment);
app.get("/thumbnails/:assetId.jpg", servePosterThumbnail);

app.listen(8080);
